<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('information_officer');
$user=current_user();$db=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);
function cp_e($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function cp_has(mysqli $db,string $table):bool{$s=$db->prepare("SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?");if(!$s)return false;$s->bind_param('s',$table);$s->execute();$ok=(bool)$s->get_result()->fetch_row();$s->close();return $ok;}
function cp_cols(mysqli $db,string $table):array{$out=[];$r=$db->query("SELECT column_name FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='".$db->real_escape_string($table)."'");if($r)while($x=$r->fetch_assoc())$out[]=$x['column_name'];return $out;}
function cp_log(mysqli $db,int $uid,string $action,string $type,string $id):void{if(!cp_has($db,'io_audit_events'))return;$s=$db->prepare("INSERT INTO io_audit_events(actor_user_id,action,entity_type,entity_id) VALUES(?,?,?,?)");if($s){$s->bind_param('isss',$uid,$action,$type,$id);$s->execute();$s->close();}}
if(session_status()!==PHP_SESSION_ACTIVE)session_start();if(empty($_SESSION['cp_csrf']))$_SESSION['cp_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['cp_csrf'];
$tab=(string)($_GET['tab']??'consents');if(!in_array($tab,['consents','purposes','processing'],true))$tab='consents';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(400);exit('Invalid security token. Refresh and try again.');}
 $action=(string)($_POST['action']??'');
 try{
  if($action==='purpose'){
   $type=trim((string)($_POST['consent_type']??''));$name=trim((string)($_POST['purpose_name']??''));$purpose=trim((string)($_POST['purpose_description']??''));$notice=trim((string)($_POST['notice_version']??''));$rec=trim((string)($_POST['recipients']??''));$ret=trim((string)($_POST['retention_rule']??''));$required=isset($_POST['is_required'])?1:0;
   if(!preg_match('/^[a-zA-Z0-9_]{2,80}$/',$type)||$name===''||$purpose===''||$notice==='')throw new RuntimeException('Enter a valid consent type, purpose name, purpose description and privacy notice version.');
   $s=$db->prepare("INSERT INTO io_consent_purpose_registry(consent_type,purpose_name,purpose_description,notice_version,recipients,retention_rule,is_required,is_active,created_by) VALUES(?,?,?,?,?,?,?,1,?) ON DUPLICATE KEY UPDATE purpose_name=VALUES(purpose_name),purpose_description=VALUES(purpose_description),notice_version=VALUES(notice_version),recipients=VALUES(recipients),retention_rule=VALUES(retention_rule),is_required=VALUES(is_required),is_active=1,updated_at=CURRENT_TIMESTAMP");
   $s->bind_param('ssssssii',$type,$name,$purpose,$notice,$rec,$ret,$required,$uid);if(!$s->execute())throw new RuntimeException('Could not save purpose mapping.');$s->close();cp_log($db,$uid,'consent_purpose_saved','consent_purpose',$type);$msg='Consent purpose mapping saved.';
  }elseif($action==='purpose_status'){
   $id=(int)($_POST['id']??0);$active=(int)($_POST['is_active']??0);$active=$active?1:0;$s=$db->prepare("UPDATE io_consent_purpose_registry SET is_active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?");$s->bind_param('ii',$active,$id);$s->execute();$s->close();cp_log($db,$uid,'consent_purpose_status_updated','consent_purpose',(string)$id);$msg='Purpose mapping status updated. Existing candidate consent records were not changed.';
  }elseif($action==='processing'){
   if(!cp_has($db,'io_processing_activities')||!cp_has($db,'io_processing_controls'))throw new RuntimeException('Import the consent and processing migration before adding processing activities.');
   $name=trim((string)($_POST['activity_name']??''));$owner=trim((string)($_POST['business_owner']??''));$purpose=trim((string)($_POST['purpose']??''));$pic=trim((string)($_POST['personal_information_categories']??''));$dsc=trim((string)($_POST['data_subject_categories']??''));$basis=trim((string)($_POST['lawful_basis']??''));$collect=trim((string)($_POST['collection_method']??''));$use=trim((string)($_POST['use_description']??''));$share=trim((string)($_POST['sharing_description']??''));$permission=trim((string)($_POST['permission_scope']??''));$rec=trim((string)($_POST['recipients']??''));$safe=trim((string)($_POST['security_safeguards']??''));$ret=trim((string)($_POST['retention_rule']??''));$cross=($_POST['cross_border_transfer']??'no')==='yes'?'yes':'no';$due=trim((string)($_POST['review_due_date']??''));
   if(!$name||!$owner||!$purpose||!$pic||!$dsc||!$basis||!$collect||!$use||!$share||!$permission||!$safe)throw new RuntimeException('Complete all required processing activity fields.');
   $db->begin_transaction();
   $s=$db->prepare("INSERT INTO io_processing_activities(activity_name,business_owner,purpose,personal_information_categories,data_subject_categories,lawful_basis,recipients,security_safeguards,cross_border_transfer,review_due_date,created_by) VALUES(?,?,?,?,?,?,?,?,?,NULLIF(?,''),?)");
   $s->bind_param('ssssssssssi',$name,$owner,$purpose,$pic,$dsc,$basis,$rec,$safe,$cross,$due,$uid);if(!$s->execute())throw new RuntimeException('Could not save processing activity.');$aid=(int)$s->insert_id;$s->close();
   $s=$db->prepare("INSERT INTO io_processing_controls(activity_id,collection_method,use_description,sharing_description,permission_scope,retention_rule,created_by) VALUES(?,?,?,?,?,?,?)");$s->bind_param('isssssi',$aid,$collect,$use,$share,$permission,$ret,$uid);if(!$s->execute())throw new RuntimeException('Could not save processing controls.');$s->close();$db->commit();cp_log($db,$uid,'processing_activity_created','processing_activity',(string)$aid);$msg='Processing activity and lifecycle controls saved.';
  }elseif($action==='review'){
   $cid=(int)($_POST['consent_record_id']??0);$decision=(string)($_POST['review_outcome']??'reviewed');$note=trim((string)($_POST['review_notes']??''));if(!in_array($decision,['reviewed','exception','follow_up_required','escalated'],true)||$cid<1||$note==='')throw new RuntimeException('Select a valid consent record and provide review notes.');
   $s=$db->prepare("INSERT INTO io_consent_reviews(candidate_consent_id,review_outcome,review_notes,reviewed_by) VALUES(?,?,?,?)");$s->bind_param('issi',$cid,$decision,$note,$uid);if(!$s->execute())throw new RuntimeException('Could not save consent review.');$s->close();cp_log($db,$uid,'consent_record_reviewed','candidate_consent',(string)$cid);$msg='Consent record review saved. The candidate consent itself was not changed.';
  }
 }catch(Throwable $e){$db->rollback();$msg=$e->getMessage();}
}
$consentTable=cp_has($db,'candidate_consents');$ccols=$consentTable?cp_cols($db,'candidate_consents'):[];
$consentRows=[];$summary=[];$totalConsent=0;$validConsent=0;$expiredConsent=0;$withdrawnConsent=0;
if($consentTable){
 $r=$db->query("SELECT consent_type,status,COUNT(*) n FROM candidate_consents GROUP BY consent_type,status ORDER BY consent_type,status");if($r)while($x=$r->fetch_assoc()){$summary[]=$x;$totalConsent+=(int)$x['n'];}
 $r=$db->query("SELECT COUNT(*) n FROM candidate_consents WHERE status='consented' AND (expires_at IS NULL OR expires_at>NOW())");if($r)$validConsent=(int)$r->fetch_assoc()['n'];
 $r=$db->query("SELECT COUNT(*) n FROM candidate_consents WHERE status='consented' AND expires_at IS NOT NULL AND expires_at<=NOW()");if($r)$expiredConsent=(int)$r->fetch_assoc()['n'];
 $r=$db->query("SELECT COUNT(*) n FROM candidate_consents WHERE status IN('withdrawn','revoked','declined','rejected')");if($r)$withdrawnConsent=(int)$r->fetch_assoc()['n'];
 $select=['id','candidate_id','consent_type','status'];foreach(['granted_at','expires_at','consent_source','created_at','updated_at'] as $c)if(in_array($c,$ccols,true))$select[]=$c;
 $sql="SELECT ".implode(',',array_map(fn($c)=>"`$c`",$select))." FROM candidate_consents ORDER BY id DESC LIMIT 200";$r=$db->query($sql);if($r)while($x=$r->fetch_assoc())$consentRows[]=$x;
}
$purposes=[];if(cp_has($db,'io_consent_purpose_registry')){$r=$db->query("SELECT * FROM io_consent_purpose_registry ORDER BY is_active DESC,consent_type");if($r)while($x=$r->fetch_assoc())$purposes[]=$x;}
$activities=[];if(cp_has($db,'io_processing_activities')&&cp_has($db,'io_processing_controls')){$r=$db->query("SELECT p.*,c.collection_method,c.use_description,c.sharing_description,c.permission_scope,c.retention_rule FROM io_processing_activities p LEFT JOIN io_processing_controls c ON c.activity_id=p.id ORDER BY p.updated_at DESC LIMIT 150");if($r)while($x=$r->fetch_assoc())$activities[]=$x;}
$recentReviews=[];if(cp_has($db,'io_consent_reviews')){$r=$db->query("SELECT * FROM io_consent_reviews ORDER BY created_at DESC LIMIT 30");if($r)while($x=$r->fetch_assoc())$recentReviews[]=$x;}
$pendingMap=0;foreach($consentRows as $row)if(!array_filter($purposes,fn($p)=>$p['consent_type']===$row['consent_type']))$pendingMap++;
?>
<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Consent &amp; Processing Management | Information Officer</title><style>
:root{--bg:#f4f6fa;--card:#fff;--tx:#172235;--mut:#687385;--line:#e1e7ef;--ac:#2458d3;--soft:#eaf1ff;--good:#16784b;--warn:#9a6500;--bad:#b42318}html[data-theme=dark]{--bg:#101722;--card:#182332;--tx:#edf2f8;--mut:#a7b3c4;--line:#2c394a;--ac:#8eb3ff;--soft:#243653;--good:#75dfaa;--warn:#ffd37d;--bad:#ff9a91;color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:14px Arial,sans-serif}.wrap{max-width:1450px;margin:auto;padding:24px 18px}header,.row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h1{margin:0 0 7px;font-size:27px}.muted{color:var(--mut);line-height:1.55}.nav{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.nav a,.btn{border:1px solid var(--line);border-radius:9px;padding:9px 12px;color:var(--tx);background:var(--card);text-decoration:none;cursor:pointer;font-weight:600;font-size:12px}.nav a.active,.primary{background:var(--ac);color:#fff;border-color:var(--ac)}.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:17px;margin:14px 0}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.stat{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px}.stat strong{display:block;font-size:25px;margin-top:5px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}label{display:block;font-weight:700;font-size:12px;margin:10px 0 5px}input,select,textarea{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--tx);font:14px Arial}textarea{min-height:75px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;padding:10px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--mut);font-size:10px;text-transform:uppercase}.pill{display:inline-block;padding:4px 8px;border-radius:20px;background:var(--soft);font-size:11px}.alert{padding:11px;border-radius:9px;background:var(--soft);margin:12px 0}.small{font-size:11px;color:var(--mut)}.inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.inline select{max-width:190px}@media(max-width:850px){.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.stats,.grid{grid-template-columns:1fr}.wrap{padding:14px 10px}}
</style></head><body><main class="wrap">
<header><div><h1>Consent &amp; Personal Information Processing</h1><div class="muted">Monitor consent evidence, declared purposes, processing permissions and information lifecycle controls.</div></div><div class="inline"><a class="btn" href="<?=cp_e(url('privacy/dashboard.php'))?>">Governance dashboard</a><button class="btn" id="theme" type="button">Theme</button></div></header>
<nav class="nav"><a class="<?=$tab==='consents'?'active':''?>" href="?tab=consents">Consent monitoring</a><a class="<?=$tab==='purposes'?'active':''?>" href="?tab=purposes">Consent purposes</a><a class="<?=$tab==='processing'?'active':''?>" href="?tab=processing">Processing inventory</a><a href="<?=cp_e(url('privacy/requests.php'))?>">Data subject requests</a><a href="<?=cp_e(url('privacy/operators.php'))?>">Operators</a></nav>
<?php if($msg!==''):?><div class="alert"><?=cp_e($msg)?></div><?php endif;?><?php if(!cp_has($db,'io_consent_purpose_registry')||!cp_has($db,'io_consent_reviews')||!cp_has($db,'io_processing_controls')):?><div class="alert">Supporting consent and processing tables are not fully installed. Import <strong>database/consent_personal_information_processing_migration.sql</strong> before using all functions.</div><?php endif;?>
<div class="stats"><div class="stat"><span class="muted">Consent records</span><strong><?=$totalConsent?></strong></div><div class="stat"><span class="muted">Currently consented and unexpired</span><strong><?=$validConsent?></strong></div><div class="stat"><span class="muted">Expired consent records</span><strong><?=$expiredConsent?></strong></div><div class="stat"><span class="muted">Withdrawn / declined</span><strong><?=$withdrawnConsent?></strong></div></div>
<?php if($tab==='consents'):?>
<section class="card"><h2>Consent status by purpose</h2><p class="muted">Live read-only view of candidate consent evidence. Expired, withdrawn or declined records must not be treated as current consent. A consent record is not a substitute for documenting the lawful basis for each processing activity.</p>
<?php if(!$consentTable):?><div class="alert">The platform's candidate_consents table is not installed or unavailable.</div><?php else:?><div class="scroll"><table><tr><th>Consent type</th><th>Status</th><th>Records</th><th>Purpose mapping</th></tr><?php foreach($summary as $x):$mapped=false;foreach($purposes as $p)if($p['consent_type']===$x['consent_type']&&$p['is_active'])$mapped=true;?><tr><td><?=cp_e($x['consent_type'])?></td><td><span class="pill"><?=cp_e($x['status'])?></span></td><td><?=(int)$x['n']?></td><td><?=$mapped?'<span class="pill">Mapped</span>':'<span class="pill">Needs purpose mapping</span>'?></td></tr><?php endforeach;?></table></div><?php endif;?></section>
<section class="card"><h2>Recent consent records</h2><p class="small">Latest 200 records. Candidate identifiers are displayed as internal IDs; no contact details or personal information are exposed here.</p><div class="scroll"><table><tr><th>Record ID</th><th>Candidate reference</th><th>Consent type</th><th>Status</th><th>Granted</th><th>Expires</th><th>Source</th><th>Review</th></tr><?php foreach($consentRows as $x):?><tr><td><?=(int)$x['id']?></td><td>#<?=(int)$x['candidate_id']?></td><td><?=cp_e($x['consent_type'])?></td><td><span class="pill"><?=cp_e($x['status'])?></span></td><td><?=cp_e($x['granted_at']??'—')?></td><td><?=cp_e($x['expires_at']??'No expiry recorded')?></td><td><?=cp_e($x['consent_source']??'—')?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=cp_e($csrf)?>"><input type="hidden" name="action" value="review"><input type="hidden" name="consent_record_id" value="<?=(int)$x['id']?>"><select name="review_outcome"><option value="reviewed">Reviewed</option><option value="exception">Exception</option><option value="follow_up_required">Follow-up</option><option value="escalated">Escalated</option></select><input name="review_notes" required placeholder="Review note" style="max-width:160px"><button class="btn">Log</button></form></td></tr><?php endforeach;?><?php if(!$consentRows):?><tr><td colspan="8">No consent records found.</td></tr><?php endif;?></table></div></section>
<?php elseif($tab==='purposes'):?>
<section class="card"><h2>Register or update consent purpose</h2><p class="muted">Map the platform's consent type to a clear, specific purpose and privacy-notice version. This configures the purpose register only; it does not create consent or change a candidate's choice.</p><form method="post"><input type="hidden" name="csrf" value="<?=cp_e($csrf)?>"><input type="hidden" name="action" value="purpose"><div class="grid"><div><label>Consent type key (must match candidate_consents.consent_type)</label><input name="consent_type" required pattern="[A-Za-z0-9_]{2,80}" placeholder="e.g. recruiter_discovery"></div><div><label>Purpose name</label><input name="purpose_name" required maxlength="180" placeholder="Recruiter discovery"></div><div><label>Privacy notice version</label><input name="notice_version" required maxlength="40" placeholder="v1.0 / 2026-11"></div><div><label>Recipients / sharing groups</label><input name="recipients" maxlength="2000" placeholder="Authorised recruiters; approved clients"></div><div><label>Retention rule</label><input name="retention_rule" maxlength="500" placeholder="Retention period and trigger"></div><div><label><input type="checkbox" name="is_required" value="1" style="width:auto"> Required for service delivery (document justification)</label></div></div><label>Specific purpose and intended use</label><textarea name="purpose_description" required maxlength="5000"></textarea><p><button class="btn primary">Save purpose mapping</button></p></form></section>
<section class="card"><h2>Configured consent purposes</h2><div class="scroll"><table><tr><th>Consent type</th><th>Purpose</th><th>Notice</th><th>Recipients</th><th>Retention</th><th>Required</th><th>Status</th><th>Action</th></tr><?php foreach($purposes as $p):?><tr><td><?=cp_e($p['consent_type'])?></td><td><strong><?=cp_e($p['purpose_name'])?></strong><br><?=cp_e($p['purpose_description'])?></td><td><?=cp_e($p['notice_version'])?></td><td><?=cp_e($p['recipients'])?></td><td><?=cp_e($p['retention_rule'])?></td><td><?=$p['is_required']?'Yes':'No'?></td><td><?=$p['is_active']?'Active':'Inactive'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=cp_e($csrf)?>"><input type="hidden" name="action" value="purpose_status"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><input type="hidden" name="is_active" value="<?=$p['is_active']?0:1?>"><button class="btn"><?=$p['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?><?php if(!$purposes):?><tr><td colspan="8">No purpose mappings configured.</td></tr><?php endif;?></table></div></section>
<?php else:?>
<section class="card"><h2>Register processing activity and permissions</h2><p class="muted">Document the information lifecycle: collection, use, sharing, permitted access, lawful basis, safeguards and retention. Record a lawful basis under POPIA only after organisational/legal validation.</p><form method="post"><input type="hidden" name="csrf" value="<?=cp_e($csrf)?>"><input type="hidden" name="action" value="processing"><div class="grid"><div><label>Activity name</label><input name="activity_name" required maxlength="180"></div><div><label>Business owner / responsible team</label><input name="business_owner" required maxlength="180"></div><div><label>Personal information categories</label><input name="personal_information_categories" required placeholder="Identity, contact, education"></div><div><label>Data subject categories</label><input name="data_subject_categories" required placeholder="Candidates, employees, clients"></div><div><label>Lawful basis / POPIA justification</label><select name="lawful_basis" required><option value="">Select and verify</option><option value="consent">Consent</option><option value="contract">Contract</option><option value="legal_obligation">Legal obligation</option><option value="public_law_duty">Public law duty</option><option value="legitimate_interest">Other applicable POPIA ground (verify)</option></select></div><div><label>Next review date</label><input type="date" name="review_due_date"></div><div><label>Collection method / source</label><input name="collection_method" required placeholder="Portal form, application, integration"></div><div><label>Recipients / access groups</label><input name="recipients" placeholder="Authorised role groups"></div><div><label>Cross-border transfer</label><select name="cross_border_transfer"><option value="no">No / not identified</option><option value="yes">Yes / assessment required</option></select></div></div><label>Processing purpose</label><textarea name="purpose" required></textarea><label>How the information is used</label><textarea name="use_description" required></textarea><label>How information is shared or disclosed</label><textarea name="sharing_description" required></textarea><label>Permissions and access restrictions</label><textarea name="permission_scope" required placeholder="Roles permitted to access, actions allowed, approval limits"></textarea><label>Retention rule / deletion trigger</label><textarea name="retention_rule"></textarea><label>Security safeguards</label><textarea name="security_safeguards" required></textarea><p><button class="btn primary">Save processing activity</button></p></form></section>
<section class="card"><h2>Processing activity register</h2><div class="scroll"><table><tr><th>Activity / owner</th><th>Purpose / basis</th><th>Collection</th><th>Use</th><th>Sharing</th><th>Permissions</th><th>Retention</th><th>Cross-border</th><th>Status</th></tr><?php foreach($activities as $a):?><tr><td><strong><?=cp_e($a['activity_name'])?></strong><br><?=cp_e($a['business_owner'])?><br><span class="small"><?=cp_e($a['personal_information_categories'])?></span></td><td><?=cp_e($a['purpose'])?><br><span class="pill"><?=cp_e($a['lawful_basis'])?></span></td><td><?=cp_e($a['collection_method'])?></td><td><?=cp_e($a['use_description'])?></td><td><?=cp_e($a['sharing_description'])?><br><?=cp_e($a['recipients'])?></td><td><?=cp_e($a['permission_scope'])?></td><td><?=cp_e($a['retention_rule'])?></td><td><?=cp_e($a['cross_border_transfer'])?></td><td><?=cp_e($a['status'])?></td></tr><?php endforeach;?><?php if(!$activities):?><tr><td colspan="9">No processing activities recorded.</td></tr><?php endif;?></table></div></section>
<?php endif;?>
<section class="card"><p class="small">This module is a governance register. It does not automatically grant, revoke or amend candidate consent, enforce access restrictions in other modules, or delete information. Candidate consent choices remain controlled through candidate-facing workflows. Configure and enforce permissions in the relevant application modules and validate lawful grounds, notices, retention and sharing arrangements with the organisation's POPIA governance process.</p></section>
</main><script>const root=document.documentElement;try{if(localStorage.getItem('io-theme')==='dark')root.dataset.theme='dark'}catch(e){}document.getElementById('theme').onclick=()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('io-theme',root.dataset.theme)}catch(e){}};</script></body></html>
